"""Marketing — cours rédigés pour être compris (style Écosphère), d'après le cours partie 1,
le chap. 1 suite, le chap. 2, le marketing stratégique suite et la dernière partie."""
from lib import Cours


def ch1():
    c = Cours()
    c.intro('De quoi parle ce chapitre ?',
            'On imagine souvent le marketing comme de la publicité. C\'est beaucoup plus large : c\'est tout ce qui permet à une entreprise de <b>comprendre ses clients</b> et de leur proposer une offre qu\'ils jugent <b>meilleure que celle des concurrents</b>. Sans cela, dit le cours, la finance, la comptabilité ou la production ne servent pas à grand-chose : il faut d\'abord qu\'il y ait une demande.',
            ['Comment définir le marketing ?', 'Qu\'est-ce que la valeur perçue et comment l\'augmenter ?', 'Besoin, désir, demande : quelle différence ?', 'Qu\'est-ce qu\'un marché en marketing, et quel est son environnement ?', 'Comment le marketing est-il devenu central dans les entreprises ?'])

    c.sec('I. Définitions du marketing')
    c.idee('Le marketing, c\'est <b>s\'adapter aux clients</b> pour leur offrir plus de valeur que les concurrents, et en tirer profit.')
    c.p('Le cours donne trois formulations simples, puis deux définitions de référence :')
    c.ul(['relier l\'entreprise aux besoins de ses clients pour avoir le bon produit, au bon endroit, au bon moment ;', 'atteindre les objectifs de l\'entreprise en répondant mieux que la concurrence aux besoins du client ;', 'identifier, anticiper et satisfaire les exigences du client de façon efficace et rentable.'])
    c.df('Marketing (définition de l\'AMA)', 'Fonction de l\'organisation et ensemble de processus visant à créer, communiquer et délivrer de la valeur aux clients et à gérer la relation client d\'une manière qui bénéficie à l\'organisation et à ses parties prenantes (American Marketing Association).')
    c.df('Marketing (définition du Mercator)', '« Effort d\'adaptation des organisations à des marchés concurrentiels, pour influencer en leur faveur le comportement des publics dont elles dépendent, par une offre dont la valeur perçue est durablement supérieure à celle des concurrents. »')
    c.p('Ces définitions se complètent. On peut en tirer <b>trois idées</b> qui structurent tout le cours.')
    c.h3('1. Un effort constant d\'adaptation')
    c.p('L\'entreprise dépend de ses clients et ne peut pas les forcer à acheter. Elle doit donc suivre en permanence leurs attentes, la concurrence, la réglementation, la technologie et l\'économie. Or la tendance naturelle est de rester dans sa « zone de confort » et de refaire ce qui marchait hier.')
    c.ex('Exemple : l\'industrie de la musique', '<p>Âge d\'or avec les vinyles et les cassettes, puis la révolution numérique : copies sans perte et téléchargement illégal. Les ventes mondiales passent de 28,6 milliards de dollars en 1999 à moins de 15 milliards en 2010 (IFPI). Elles ne repartent qu\'en 2015, grâce aux concerts, au téléchargement légal et au streaming. Une adaptation douloureuse.</p>')
    c.h3('2. Créer une valeur perçue supérieure à celle des concurrents')
    c.p('Pour que le client choisisse votre offre, il doit la percevoir comme <b>différente et meilleure</b>. Et cette valeur n\'existe pas dans l\'absolu : elle se juge <b>par rapport aux concurrents</b>, et peut disparaître quand ceux-ci progressent.')
    c.ex('Exemple : Nokia', '<p>Leader incontesté du téléphone portable jusque dans les années 2000, Nokia se fait prendre le haut de gamme par l\'iPhone et Samsung et le bas de gamme par les fabricants chinois. Sa division mobile est vendue à Microsoft fin 2013, qui s\'en sépare trois ans plus tard.</p>')
    c.h3('3. Une politique qui s\'inscrit dans la durée')
    c.p('Il ne suffit plus de conquérir des clients : il faut les <b>garder</b>. Exemple : Free et son forfait à 2 € par mois, pour recruter des clients puis les faire passer à des formules plus chères.')
    c.retenir(['Marketing = s\'adapter + offrir une valeur perçue supérieure + fidéliser.', 'Deux définitions à citer : AMA (créer, communiquer, délivrer de la valeur) et Mercator (adaptation, valeur perçue durablement supérieure).'])
    c.transition('Au cœur de ces définitions se trouve une notion clé : la valeur perçue.')

    c.sec('II. La valeur perçue')
    c.idee('Le client compare <b>ce qu\'il obtient</b> et <b>ce que ça lui coûte</b>, et il le fait avec sa propre perception, pas avec la fiche technique.')
    c.df('Valeur perçue', 'Perception par les clients de ce qu\'ils obtiennent (bénéfices perçus : le produit) pour ce qu\'ils donnent (coûts perçus : le prix, mais aussi les efforts, le temps, le risque).')
    c.tab(['Bénéfices perçus (ce que j\'obtiens)', 'Coûts perçus (ce que je donne)'], [['Produit principal, qualité, performances', 'Prix'], ['Services associés (information, conseil, SAV…)', 'Efforts (s\'informer, acheter…)'], ['Éléments intangibles portés par la marque', 'Coût de changement, temps, risque perçu']])
    c.autrement('un produit peut être excellent techniquement et pourtant mal perçu, ou banal et très bien vendu. Ce qui compte, c\'est ce que le client <b>ressent</b>.')
    c.ex('Exemple : l\'eau en bouteille', '<p>Dans le même magasin : Cristaline à 0,15 €/l, Evian à 0,39 €/l, San Pellegrino à 0,75 €/l, Iceberg Water à 16 €/l. Pourquoi payer plus du double pour de l\'eau ? Parce qu\'Evian est la seule à promettre la <b>jeunesse</b>, et les clients paient cette promesse.</p>')
    c.p('Attention au décalage entre l\'entreprise et ses clients. Chez un constructeur automobile, les efforts portent sur l\'ingénierie et la fabrication ; mais le client juge surtout le design, la marque et la relation avec le concessionnaire.')
    c.h3('Avant et après l\'achat')
    c.ul(['La valeur perçue est toujours <b>relative</b> aux offres concurrentes.', 'Avant l\'achat, elle explique la <b>décision d\'achat</b> ; après l\'achat, l\'expérience explique le <b>rachat</b>, c\'est-à-dire la fidélité.'])
    c.df('Satisfaction', 'Résultat de la comparaison entre les attentes (valeur perçue avant achat) et l\'expérience (après achat) ; elle entraîne en principe la fidélité.')
    c.df('Attrition', 'Défection ou abandon des clients, favorisés par l\'insatisfaction.')
    c.p('La valeur perçue n\'est donc ni la simple somme des bénéfices, ni la seule qualité ; et elle varie d\'un client à l\'autre.')
    c.h3('Comment augmenter la valeur perçue ?')
    c.p('Deux leviers : <b>augmenter les bénéfices perçus</b> ou <b>réduire les coûts perçus</b>.')
    c.tab(['Augmenter les bénéfices perçus', 'Réduire les coûts perçus'], [
        ['Innovation de concept (nouveau type de produit)', 'Baisser le prix (attention à la rentabilité)'], ['Meilleures performances', 'Changer la perception du prix : libre-service, meubles Ikea à monter, équipement bon marché et consommable rentable (imprimantes), promotions ciblées'],
        ['Identité sensorielle, design, packaging', 'Faire gagner du temps et des efforts (accès à l\'information)'], ['Services associés (accueil, conseil, maintenance…)', 'Réduire les coûts de fonctionnement et de maintenance'], ['Qualité perçue (durabilité, moins de pannes)', 'Réduire le risque perçu (certifications)'], ['Marque (style, prestige)', '']])
    c.ex('Exemples du cours', '<p><b>Le drive</b> : les prix sont les mêmes qu\'en hypermarché, mais le client gagne du temps et de l\'effort. <b>Airbus A320neo</b> (lancé en décembre 2010, plus de 4 800 exemplaires vendus en 6 ans) joue sur les deux leviers. Il apporte plus de bénéfices (+950 km d\'autonomie, +2 t de charge utile, nouvelle cabine) et coûte moins cher à exploiter (−15 % de carburant, −10 % d\'émissions).</p>')
    c.retenir(['Valeur perçue = bénéfices perçus / coûts perçus, comparés aux concurrents.', 'Avant achat → achat ; après achat → fidélité ou attrition.', 'Deux leviers : plus de bénéfices, moins de coûts (pas seulement le prix).'])
    c.transition('Le marketing ne se pratique pas partout de la même façon : le cours distingue deux « facettes ».')

    c.sec('III. Les deux facettes du marketing')
    c.tab(['Marketing codifié', 'Marketing intuitif'], [['Grandes entreprises, groupes internationaux (EDF, Procter & Gamble)', 'Entrepreneurs, jeunes entreprises'], ['Processus, outils et postes écrits et partagés', 'Créativité et vision'], ['Beaucoup d\'études et de panels', 'Peu d\'études, veille informelle, intuition'], ['Peu de place à la créativité', 'La vision doit quand même être validée par quelques faits']])
    c.p('Dans les deux cas, la démarche s\'organise autour de l\'<b>audit</b> (analyse de la situation), des <b>études de marché</b> (qualitatives, quantitatives, tests) et du <b>marketing mix</b> (les 4P : produit, prix, place, promotion).')

    c.sec('IV. Les concepts clés : besoin, désir, demande, échange')
    c.idee('On part d\'un <b>manque</b> (besoin), qui se tourne vers un <b>objet précis</b> (désir), qui ne devient une <b>demande</b> que si l\'on a les moyens et l\'envie d\'acheter.')
    c.df('Produit', 'Tout ce qui peut être offert sur un marché de façon à satisfaire un besoin.')
    c.df('Besoin', 'Sentiment de manque ou de privation portant sur des éléments nécessaires (nourriture, air, eau, vêtements, abri…) ; les besoins préexistent, ils sont innés.')
    c.df('Désir', 'Matérialisation du besoin : il porte sur un objet spécifique ; le marketing, avec d\'autres forces sociales, influence les désirs mais ne crée pas les besoins.')
    c.df('Demande', 'Désir d\'acheter certains produits soutenu par un pouvoir et un vouloir d\'achat.')
    c.pas('Exemple', ['Besoin : avoir soif.', 'Désir : un Coca bien frais.', 'Demande : j\'ai 2 € et je décide de l\'acheter.', 'Le cours cite le bijou en or : beaucoup le désirent, mais seule 1 personne sur 7 parvient à l\'acheter.'])
    c.pourquoi('Le marketing crée-t-il des besoins ?', 'Non, répond le cours : les besoins sont innés et préexistent. Le marketing <b>influence les désirs</b>, avec d\'autres forces sociales. C\'est la réponse à l\'accusation selon laquelle il pousserait à acheter ce dont on n\'a pas besoin.')
    c.p('<b>Pyramide de Maslow</b> : les besoins se hiérarchisent, de la base au sommet : physiologiques → sécurité → amour et appartenance → estime → accomplissement de soi.')
    c.p('Les besoins sont difficiles à cerner. Il faut distinguer les besoins <b>exprimés</b> (ce que le client dit), <b>réels</b> (ce qu\'il veut dire), <b>latents</b> (ce à quoi il ne pense pas), <b>rêvés</b> et <b>profonds</b> (ce qui le motive secrètement). S\'en tenir aux besoins exprimés serait réducteur.')
    c.tab(['Type de demande', 'Exemple'], [['Négative', 'Soins dentaires, assurance décès'], ['Absente ou latente', 'Produit ignoré ou pas encore inventé'], ['Irrégulière', 'Consommation irrégulière dans le temps'], ['Déclinante', 'Fax'], ['Soutenue', 'Nourriture'], ['Excessive', 'Circulation'], ['Indésirable', 'Drogue']])
    c.df('Échange', 'Situation qui suppose cinq conditions : deux parties, chacune possède quelque chose qui a de la valeur pour l\'autre, chacune peut communiquer et livrer, chacune est libre d\'accepter ou de refuser, et chacune juge l\'échange adapté à son problème.')
    c.retenir(['Besoin (inné) → désir (objet précis) → demande (pouvoir + vouloir d\'achat).', 'Le marketing influence les désirs, il ne crée pas les besoins.', 'L\'échange suppose cinq conditions ; il conduit à la notion de marché.'])
    c.transition('Qui dit échange dit marché. En marketing, ce mot a un sens précis.')

    c.sec('V. Le marché')
    c.df('Marché (en marketing)', 'Couple produit/client, c\'est-à-dire l\'ensemble de l\'offre et de la demande et de leurs acteurs (concurrents, distributeurs, consommateurs actuels et potentiels) ; il se définit toujours géographiquement.')
    c.p('Cinq acteurs : les <b>clients</b>, les <b>producteurs</b>, les <b>distributeurs</b>, les <b>influenceurs</b> (prescripteurs) et les <b>institutions</b> qui régulent. Exemple du cours, le médicament sur ordonnance : le médecin prescrit, le pharmacien distribue, la sécurité sociale rembourse, le patient consomme.')
    c.idee('Un produit n\'a pas qu\'un seul marché. Les concurrents ne sont pas seulement ceux qui vendent la même chose, mais tous ceux qui répondent au même besoin.')
    c.tab(['Type de marché', 'Définition', 'Exemples'], [['Principal', 'Produits directement concurrents (même technologie, même fonction)', 'L\'automobile'], ['Indirect', 'Produits différents, même fonction', 'Avion vs train'], ['Générique', 'Tout ce qui satisfait le même besoin, autrement', 'La visioconférence (au lieu de voyager)'], ['Support', 'Ce qui est nécessaire à l\'usage du produit', 'Routes, essence']])
    c.df('Niche', 'Marché étroit protégé par des barrières à l\'entrée, sur lequel les entreprises sont relativement à l\'abri de la concurrence ; un petit marché n\'est une niche que s\'il est défendable.')
    c.ex('Cas GoPro', '<p>Caméra miniature, étanche et antichoc lancée en 2005 ; 6,6 millions d\'unités vendues en 2015. Mais un marché devenu grand attire les géants de l\'électronique : en 2016, les ventes chutent, avec des pertes et des licenciements. Une niche n\'est protégée que tant qu\'elle reste défendable.</p>')
    c.df('Marché induit', 'Marché qui dépend directement d\'un autre marché (ventes liées) : les applications dépendent du marché des smartphones.')
    c.df('Marché captif', 'Marché où les clients sont contraints d\'acheter une marque ou un produit donné : l\'App Store pour les utilisateurs d\'iPhone.')
    c.p('On distingue enfin les marchés <b>B to C</b> (particuliers) et <b>B to B</b> (professionnels). En France, une voiture neuve sur deux est vendue à une entreprise, et on ne la vend pas à Hertz comme à un particulier.')
    c.retenir(['Marché = couple produit/client, défini géographiquement.', 'Principal, indirect, générique, support : penser à tous les concurrents du besoin.', 'Niche = petit marché défendable ; induit, captif ; B to C et B to B.'])

    c.sec('VI. L\'environnement')
    c.idee('L\'entreprise ne vit pas seule sur son marché : la technologie, l\'écologie, la démographie, l\'économie et la loi peuvent changer les règles du jeu.')
    c.df('Environnement', 'Ensemble des acteurs et domaines qui influencent, de près ou de loin, le marché sur lequel l\'entreprise agit.')
    c.tab(['Environnement', 'Questions à se poser'], [['Technologique', 'Quelles innovations peuvent modifier nos processus, nos offres, nos coûts, nos prix ?'], ['Écologique', 'Quels risques anticiper ? Quelles normes ? Quelle rareté des ressources ?'], ['Démographique', 'Faut-il revoir nos cibles ?'], ['Économique', 'Croissance, prix, effet de la conjoncture sur nos clients et nos concurrents ?'], ['Légal', 'Quelles lois à venir touchent nos clients, notre distribution, notre communication, nos prix ?']])
    c.transition('Plus l\'environnement devient complexe, plus le marketing prend de place dans l\'entreprise : c\'est son histoire.')

    c.sec('VII. L\'évolution du marketing et les quatre optiques')
    c.idee('Le rôle du marketing dépend du <b>rapport entre l\'offre et la demande</b>. Quand on manque de produits, il suffit de produire ; quand il y en a trop, il faut séduire le client.')
    c.tab(['Économie', 'Offre / demande', 'Qui domine', 'Rôle du marketing'], [['De production', 'Offre < demande', 'Le producteur', 'Presque inutile : tout ce qu\'on produit se vend ; entreprise introvertie, dominée par les ingénieurs'], ['De distribution', 'Offre = demande', 'Le vendeur', 'Savoir vendre : publicité, promotion ; début des études de marché'],
                                                                              ['De marché', 'Offre > demande', 'Le consommateur', 'S\'adapter au client, segmenter ; entreprise extravertie'], ['D\'environnement', 'Offre > demande', 'Le milieu', 'Tenir compte de tout l\'environnement (technologie, écologie, société, loi)']])
    c.p('Depuis les années 1970 : tissu industriel dense, cycles de vie plus courts, consommateurs plus instruits, le prix n\'est plus le seul critère. Aujourd\'hui s\'ajoutent la société <b>postmoderne</b> (individualisme, éthique, écologie), la <b>veille</b> permanente et le <b>micro-marketing</b> (marketing direct, au plus près de chaque client).')
    c.h3('Les quatre optiques')
    c.df('Optique production', 'Quand la demande excède l\'offre : le consommateur choisit selon le prix et la disponibilité ; priorité à la capacité de production et à la distribution.')
    c.df('Optique produit', 'Domaine où la technologie domine : le consommateur préfère le produit le plus performant ; priorité à la qualité du produit.')
    c.df('Optique vente', 'Le consommateur n\'achète pas assez de lui-même : l\'entreprise doit stimuler l\'intérêt (partis politiques, vendeurs de meubles, promoteurs immobiliers, certaines assurances).')
    c.df('Optique marketing', 'Quatre idées : un choix de marché (ciblage), une orientation centrée sur le client, un marketing coordonné diffusé à tout le personnel et la rentabilité (profit, intérêt général ou service public selon l\'organisation).')
    c.synthese(['Le marketing = s\'adapter aux clients pour offrir une <b>valeur perçue</b> supérieure à celle des concurrents, dans la durée.', 'Valeur perçue = bénéfices perçus face aux coûts perçus ; on l\'augmente par les deux leviers.', 'Besoin → désir → demande ; le marketing influence les désirs.', 'Le marché se lit largement (principal, indirect, générique, support) et dans son environnement.', 'L\'optique marketing (ciblage, client, coordination, rentabilité) s\'impose quand l\'offre dépasse la demande.'])
    return c


def ch2():
    c = Cours()
    c.intro('De quoi parle ce chapitre ?',
            'Le chapitre 1 expliquait ce qu\'est le marketing. Celui-ci passe à la <b>stratégie</b> : comment une entreprise analyse sa situation, décide où investir et choisit sa façon de battre la concurrence. On suit un chemin logique : <b>se fixer un cadre</b>, <b>faire le diagnostic</b>, <b>analyser son portefeuille de produits</b>, puis <b>choisir une stratégie de développement</b>.',
            ['Quelle différence entre marketing stratégique et opérationnel ?', 'Comment faire un diagnostic (PESTEL, SWOT, Porter) ?', 'Comment juger ses produits (ADL, BCG, McKinsey) ?', 'Quelles stratégies pour se développer (coûts, spécialisation, différenciation, innovation, croissance externe) ?'])

    c.sec('I. Le vocabulaire de la stratégie')
    c.idee('Avant d\'agir, l\'entreprise dit <b>qui elle est</b> (mission), <b>où elle veut aller</b> (vision) et <b>comment</b> (stratégie).')
    c.tab(['Terme', 'Définition'], [['Mission', 'Propos fondamental de l\'organisation, en rapport avec les valeurs et les attentes des parties prenantes'], ['Vision (intention stratégique)', 'État futur souhaité : l\'aspiration de l\'organisation'], ['But', 'Déclaration générale d\'intention'], ['Objectif', 'Quantification (si possible) ou intention plus précise'], ['Compétences fondamentales', 'Ressources, procédés et aptitudes qui permettent d\'obtenir un avantage concurrentiel'], ['Stratégie', 'Orientation à long terme'], ['Contrôle', 'Évaluation de l\'efficacité et correction si nécessaire']])
    for t, d in (('Mission', 'Propos fondamental de l\'organisation, en rapport avec les valeurs et les attentes des parties prenantes.'), ('Compétences fondamentales', 'Ressources, procédés et aptitudes qui permettent d\'obtenir un avantage concurrentiel.'), ('Stratégie', 'Orientation à long terme de l\'organisation.')):
        c.df(t, d, show=False)
    c.ex('Exemple : British Airways', '<p><b>Mission</b> : être la meilleure et la plus prospère des compagnies, construire la première alliance globale. <b>Vision</b> : être toujours le premier choix des clients grâce à une qualité inégalée. <b>Compétence fondamentale</b> : « n\'importe qui peut faire voler un avion, mais peu d\'organisations excellent dans le service aux clients » (difficile à copier). <b>Stratégie</b> : rester en tête de la globalisation du transport aérien et garder la priorité à la qualité de service.</p>')

    c.sec('II. Marketing stratégique et marketing opérationnel')
    c.idee('Le marketing <b>stratégique</b> choisit la direction (où aller, pour qui) ; le marketing <b>opérationnel</b> met en œuvre (comment y aller, au quotidien).')
    c.df('Marketing stratégique', 'Orientations générales de l\'entreprise : positionner l\'entreprise, ses marques et ses gammes, fixer à moyen et long terme ses orientations de développement et énoncer un plan stratégique clair ; il relève de la direction.')
    c.df('Marketing opérationnel', 'Ensemble des tactiques au service de la stratégie : communication clients et prospects, appui à la force de vente, lancement de produits, suivi du marché (CA, volumes, PdM), actions avec fournisseurs et distributeurs.')
    c.h3('La démarche : le modèle SOSTAC (Paul Smith)')
    c.tab(['Étape', 'Ce qu\'on fait'], [['<b>S</b>ituation analysis', 'Comprendre le contexte : macro-environnement, micro-environnement (fournisseurs, clients, distributeurs, concurrents, actionnaires), opportunités, menaces, forces, faiblesses'], ['<b>O</b>bjectives', 'Se fixer des objectifs SMART'], ['<b>S</b>trategy', 'Segmenter, cibler, se positionner'], ['<b>T</b>actics', 'Définir le marketing mix : produit, prix, distribution, communication'], ['<b>A</b>ctions', 'Passer à l\'action, former et informer la force de vente'], ['<b>C</b>ontrol', 'Comparer prévisions et réalité, mesurer le retour sur investissement']])
    c.df('Objectif SMART', 'Objectif spécifique au contexte, mesurable (chiffré), ambitieux, réaliste et inscrit dans le temps.')
    c.df('Segmentation', 'Division d\'un marché hétérogène en sous-groupes homogènes selon des critères propres au secteur.')
    c.df('Ciblage', 'Choix d\'un ou plusieurs segments (cibles) sur lesquels l\'entreprise concentre ses efforts et adapte son marketing opérationnel.')
    c.df('Positionnement', 'Image que l\'entreprise veut donner au marché et à ses partenaires.')
    c.autrement('on découpe le marché en groupes de clients qui se ressemblent (segmentation), on choisit ceux qu\'on vise (ciblage), puis on décide de l\'image qu\'on veut avoir à leurs yeux (positionnement).')
    c.retenir(['Stratégique = direction ; opérationnel = mise en œuvre.', 'SOSTAC : Situation, Objectifs SMART, Stratégie (segmentation, ciblage, positionnement), Tactiques (4P), Actions, Contrôle.'])
    c.transition('Tout commence par la « S » de SOSTAC : le diagnostic.')

    c.sec('III. Le diagnostic stratégique')
    c.idee('Avant de choisir une stratégie, on regarde <b>dehors</b> (le marché, l\'environnement, la concurrence) et <b>dedans</b> (les ressources de l\'entreprise), pour vérifier que les deux collent.')
    c.p('Le diagnostic combine une <b>étude du marché et de la concurrence</b> et une <b>étude des ressources internes</b>. La nature de l\'environnement change la méthode : simple et stable, on prévoit à partir du passé ; dynamique, on raisonne par scénarios ; complexe, on décentralise et on apprend par l\'expérience.')
    c.h3('A. PESTEL : l\'environnement général')
    c.df('PESTEL', 'Grille d\'analyse du macro-environnement : facteurs politiques, économiques, socioculturels, technologiques, écologiques et légaux.')
    c.tab(['Facteur', 'Exemples du cours'], [['Politique / légal', 'Lois sur les monopoles, environnement, fiscalité, commerce extérieur, droit du travail, stabilité du gouvernement'], ['Économique', 'Cycles, revenu disponible, PNB, politique monétaire, inflation, taux d\'intérêt, chômage, coût de l\'énergie'], ['Socioculturel', 'Démographie, revenus, mobilité sociale, modes de vie, rapport aux loisirs et au travail, éducation'], ['Technologique', 'R&D, investissements, découvertes, vitesse de diffusion, obsolescence']])
    c.p('Exemple du cours : le vieillissement de la population peut pousser une entreprise vers des produits adaptés aux personnes âgées.')
    c.h3('B. SWOT : croiser l\'intérieur et l\'extérieur')
    c.df('SWOT', 'Diagnostic stratégique croisant l\'analyse interne (forces, faiblesses) et l\'analyse externe (opportunités, menaces), développé en 1965 par Learned, Christensen, Andrews et Guth (Harvard Business School).')
    c.autrement('forces et faiblesses, c\'est ce que l\'entreprise <b>est</b> (interne) ; opportunités et menaces, c\'est ce qui lui <b>arrive</b> (externe).')
    c.p('Le raisonnement se fait en cinq phases : menaces, opportunités et facteurs clés de succès ; forces, faiblesses et compétences distinctives ; recensement des actions possibles ; valeurs (responsabilité sociale, dirigeants) ; formulation de la stratégie.')
    c.tab(['', 'Opportunités', 'Menaces'], [['<b>Forces</b>', 'Stratégie d\'<b>attaque</b> : en profiter au maximum', 'Stratégie d\'<b>ajustement</b> : consolider ses points forts'], ['<b>Faiblesses</b>', 'Stratégie de <b>défense</b> : contourner les difficultés', 'Stratégie de <b>survie</b> : surveiller de près la concurrence']])
    c.h3('C. Les 5 + 1 forces de Porter : l\'intensité de la concurrence')
    c.idee('Un secteur est d\'autant moins attractif que les « forces » qui pèsent sur ses entreprises sont fortes. Les concurrents directs ne sont qu\'une force parmi six.')
    c.df('Modèle des 5 (+1) forces de Porter', 'Outil qui analyse l\'intensité concurrentielle d\'un secteur ou d\'un domaine d\'activité stratégique (DAS) : nouveaux entrants, produits de substitution, pouvoir des clients, pouvoir des fournisseurs, rivalité entre concurrents, plus les contraintes réglementaires des pouvoirs publics.')
    c.df('Domaine d\'activité stratégique (DAS)', 'Sous-ensemble homogène de l\'activité de l\'entreprise (couple produit/marché) sur lequel on analyse la concurrence et on définit une stratégie.')
    c.tab(['Force', 'Elle est forte quand…'], [['Nouveaux entrants', 'Il y a peu d\'économies d\'échelle, peu de capitaux nécessaires, un accès facile à la distribution et à la technologie, peu de fidélité à la marque'], ['Produits de substitution', 'Les substituts sont meilleurs ou moins chers, et il est facile d\'en changer'], ['Pouvoir des fournisseurs', 'Ils sont peu nombreux, ont une marque forte, peuvent s\'intégrer en aval'], ['Pouvoir des clients', 'Ils sont concentrés, les produits sont standardisés, changer de fournisseur est facile'], ['Rivalité', 'Beaucoup de concurrents de taille égale, coûts fixes élevés (guerre des prix), produits peu différenciés, barrières à la sortie élevées'], ['+1 Pouvoirs publics', 'Licences (téléphonie mobile), subventions absentes, normes de sécurité, interdictions']])
    c.p('Exemple du cours : l\'<b>hexagone sectoriel</b> du livre en 2015 note chaque force de 0 à 10 : rivalité (Hachette, Bertelsmann…), nouveaux entrants (Google Books, Amazon), fournisseurs (imprimeurs, auteurs), acheteurs (librairies, grande distribution), substituts (livre électronique), État.')
    c.retenir(['PESTEL : macro-environnement.', 'SWOT : forces/faiblesses (interne) × opportunités/menaces (externe) → attaque, ajustement, défense, survie.', 'Porter 5 + 1 : plus les forces sont fortes, moins le secteur est attractif.'])
    c.transition('Une fois le terrain analysé, on regarde ses propres produits : lesquels développer, lesquels abandonner ?')

    c.sec('IV. Juger ses produits : ADL, BCG, McKinsey')
    c.idee('Une entreprise a plusieurs produits, à des stades différents. Les matrices aident à répartir l\'argent : certains produits <b>rapportent</b> du cash, d\'autres en <b>consomment</b>.')
    c.h3('A. La matrice ADL (maturité du marché)')
    c.df('Matrice ADL (Arthur D. Little)', 'Matrice qui croise la maturité de l\'activité (démarrage, croissance, maturité, déclin) et la position concurrentielle (marginale à dominante) pour apprécier rentabilité, besoins de financement et risques.')
    c.tab(['Position concurrentielle', 'Démarrage / croissance', 'Maturité / déclin'], [['Forte / dominante', 'Bonne rentabilité, fort besoin de cash', 'Bonne rentabilité, faible besoin de cash'], ['Faible / marginale', 'Faible rentabilité, fort besoin de cash', 'Faible rentabilité, faible besoin de cash']])
    c.pourquoi('Pourquoi une activité jeune a-t-elle besoin de beaucoup de cash ?', 'Parce qu\'un marché en croissance demande d\'investir pour suivre la demande (capacités, publicité). Et une forte part de marché est rentable parce qu\'elle amplifie l\'effet d\'expérience et les économies d\'échelle.')
    c.h3('B. La matrice BCG (croissance / part de marché)')
    c.df('Matrice BCG', 'Matrice du Boston Consulting Group qui classe les produits selon la croissance du marché et la part de marché : dilemmes, stars, vaches à lait, poids morts.')
    c.tab(['Case', 'Situation', 'Rentabilité / besoins', 'Que faire ?'], [['Dilemmes', 'Marché en forte croissance, faible PdM', 'Rentabilité faible, gros besoins, gros support marketing', 'Investir pour en faire des stars, ou les laisser devenir des poids morts'], ['Stars', 'Forte croissance, forte PdM', 'Rentables mais encore gourmandes', 'Soutenir : ce sont les vaches à lait de demain'], ['Vaches à lait', 'Faible croissance, forte PdM', 'Très rentables, peu de besoins', 'Rentabiliser : elles financent le reste'], ['Poids morts', 'Faible croissance, faible PdM', 'Peu rentables, risque d\'hémorragie', 'Abandonner']])
    c.df('Vache à lait', 'Produit à forte part de marché sur un marché à faible croissance : il fournit des liquidités et consomme peu de capitaux.')
    c.df('Dilemme', 'Produit à faible part de marché sur un marché en forte croissance : il demande des capitaux pour devenir une star, sinon il deviendra un poids mort.')
    c.autrement('le portefeuille idéal est un cycle : les <b>vaches à lait</b> financent les <b>dilemmes</b> prometteurs, qui deviennent des <b>stars</b>, qui deviendront à leur tour des vaches à lait.')
    c.h3('C. La matrice McKinsey')
    c.df('Matrice McKinsey', 'Matrice qui croise l\'intérêt stratégique (attrait) du marché et la position concurrentielle en 3 × 3 cases, de « maintenir sa position de leader » à « abandon ».')
    c.tab(['Position ↓ / intérêt →', 'Fort', 'Moyen', 'Faible'], [['Forte', 'Maintenir sa position de leader', '« Surfer » sur la vague', 'Rentabiliser'], ['Moyenne', 'Améliorer sa position', 'Rentabiliser, optimiser', 'Abandon sélectif'], ['Faible', 'R&D… ou abandon ?', 'Abandon sélectif / progressif', 'Abandon']])
    c.p('Ces analyses servent à exploiter au mieux les produits, à choisir rationnellement, à évaluer les besoins financiers et à <b>équilibrer</b> le portefeuille.')
    c.warn('Ce sont des <b>outils d\'aide à la décision</b>, pas des recettes : ils ont des faiblesses et le discernement reste de rigueur.')
    c.retenir(['ADL : maturité × position → rentabilité et besoins de cash.', 'BCG : croissance × PdM → dilemmes, stars, vaches à lait, poids morts.', 'McKinsey : intérêt × position, 9 recommandations.'])
    c.transition('Reste à choisir <b>comment</b> se développer et battre la concurrence. Le cours distingue la croissance interne et la croissance externe.')

    c.sec('V. Se développer par croissance interne')
    c.idee('Quatre grandes façons de gagner : être <b>le moins cher</b>, se concentrer sur <b>un petit groupe de clients</b>, être <b>différent</b>, ou <b>innover</b>.')
    c.h3('1. La domination par les coûts')
    c.df('Domination par les coûts', 'Stratégie fondée sur la maîtrise absolue des coûts de production et de la logistique (effet d\'expérience et économies d\'échelle) pour être le producteur le moins cher.')
    c.df('Effet d\'expérience', 'Le coût unitaire décroît d\'un pourcentage constant chaque fois que la production cumulée double ; causes : apprentissage, modifications des produits ou de la fabrication, économies d\'échelle.')
    c.df('Économie d\'échelle', 'Baisse du coût unitaire quand le nombre d\'unités par série augmente, par dilution des frais fixes.')
    c.autrement('plus on a produit depuis le début, mieux on sait faire, donc moins ça coûte (expérience). Plus on produit en une fois, plus les frais fixes sont répartis (échelle).')
    c.pas('Le cercle vertueux', ['L\'effet d\'expérience fait baisser les coûts.', 'Des coûts plus bas donnent un avantage concurrentiel.', 'L\'avantage permet de gagner des parts de marché.', 'Plus de parts de marché, c\'est plus de volume, donc encore plus d\'expérience et d\'économies d\'échelle.'])
    c.ul(['<b>Avantages</b> : mieux placée en cas de guerre des prix ; dissuade les concurrents moins performants ; plus de poids face aux fournisseurs et aux clients.', '<b>Souplesse de prix</b> : prix de pénétration au lancement, prix réactifs en croissance, pression en maturité mais maintien des marges, flexibilité en déclin.', '<b>Conditions</b> : connaître parfaitement les facteurs clés de succès, pouvoir investir, savoir capitaliser l\'expérience ; rigueur financière et maîtrise technique.', '<b>Risques</b> : un changement technologique qui annule l\'avantage, un concurrent plus performant, la sur-standardisation, ne plus voir le marché à force de regarder les coûts.'])
    c.df('Délocalisation', 'Faire produire au moins cher dans des pays à faibles coûts pour vendre dans les pays à fort pouvoir d\'achat ; une des solutions de la domination par les coûts, qui suppose une main-d\'œuvre compétente et une faisabilité logistique.')
    c.p('Limites de la délocalisation : chômage dans les pays riches (donc baisse du pouvoir d\'achat) et pays à bas coûts cantonnés aux tâches à faible valeur ajoutée.')
    c.h3('2. La spécialisation (stratégie de niche)')
    c.df('Spécialisation (niche)', 'Stratégie par laquelle l\'entreprise s\'assigne une cible restreinte et adapte son offre pour satisfaire mieux que les autres certaines exigences de ces clients.')
    c.ul(['<b>Avantages</b> : prix plus élevés, clients fidèles, peu de nouveaux entrants, compétences pointues.', '<b>Conditions</b> : structure légère, marketing et R&D performants, savoir utiliser des ressources extérieures.', '<b>Risques</b> : écart de prix trop grand, produits qui vieillissent, dépendance au segment, différences qui s\'effacent.'])
    c.h3('3. La différenciation')
    c.df('Différenciation', 'Stratégie qui distingue l\'offre par une ou plusieurs variables du marketing mix ; la différence doit être perçue et valorisée par le marché.')
    c.pourquoi('Pourquoi la différence doit-elle être « perçue et valorisée » ?', 'Parce qu\'une différence que le client ne voit pas ou qui ne compte pas pour lui ne justifie aucun prix plus élevé. On retrouve la <b>valeur perçue</b> du chapitre 1.')
    c.ul(['<b>Par le produit</b> : fonctionnalité, fiabilité, performance, réparabilité, conformité, style, durabilité, design.', '<b>Par le service</b> : avant la vente (aide à définir le besoin, conseil, démonstrations) et après (installation, formation, maintenance, pièces).', '<b>Par le personnel</b> : compétence, fiabilité, courtoisie, serviabilité, crédibilité, écoute.', '<b>Par l\'accès au produit</b> : couverture du territoire, expertise du réseau.', '<b>Par l\'image</b> : l\'identité voulue par l\'entreprise face à la perception du marché.'])
    c.p('Avantages : prix plus élevé, fidélité, entrée plus difficile pour les nouveaux. Risques : banalisation du marché, imitations, écart de prix trop grand.')
    c.h3('4. L\'innovation')
    c.df('Innovation (stratégie)', 'Développement et exploitation des ressources internes et de la R&D : amélioration de l\'existant ou innovation pure (nouveaux produits).')
    c.p('Ces quatre stratégies dressent des <b>barrières à l\'entrée</b>. Mais elles dépendent du marché : pour aller plus vite ou plus loin, il faut parfois grandir par l\'extérieur.')
    c.retenir(['Coûts : effet d\'expérience + économies d\'échelle.', 'Spécialisation : une cible restreinte mieux servie.', 'Différenciation : une différence perçue et valorisée (produit, service, personnel, accès, image).', 'Innovation : améliorer ou créer.'])

    c.sec('VI. Se développer par croissance externe, impartition et alliances')
    c.df('Croissance externe', 'Ensemble des opérations d\'acquisition d\'une autre entreprise (rachat) ou de fusion pour accélérer son développement.')
    c.idee('Au lieu de tout construire soi-même, on <b>achète</b> ce qui existe déjà : c\'est plus rapide, mais plus risqué et plus cher.')
    c.ul(['<b>Pourquoi</b> : s\'implanter à l\'étranger, éliminer un concurrent, acquérir des compétences (gagner du temps), sécuriser ses débouchés (intégration en aval) ou ses approvisionnements (intégration en amont).', '<b>Avantages</b> : devenir leader rapidement, élargir ses compétences, remodeler le marché, atteindre la taille critique, peser davantage face aux clients.', '<b>Inconvénients</b> : engagement difficile à défaire, capitaux énormes, équipes qui s\'adaptent mal, inquiétude des salariés, montage complexe et coûteux.'])
    c.df('Intégration verticale', 'Rachat d\'un fournisseur (intégration en amont) ou d\'un client ou distributeur (intégration en aval) pour maîtriser la filière.')
    c.df('Impartition', 'Manœuvre entre partenaires aux potentiels complémentaires (« faire ou faire faire ? ») : sous-traitance, franchise, concession ; on conserve les activités créatrices de valeur.')
    c.tab(['Technique', 'Principe'], [['Sous-traitance', 'Faire réaliser par une autre entreprise tout ou partie de ce qu\'on doit fournir à ses clients'], ['Franchise', 'Le franchiseur prête son enseigne, sa marque et son savoir-faire au franchisé, contre des droits'], ['Concession', 'Un fabricant accorde à un commerçant indépendant l\'exclusivité de revente sur une zone']])
    c.p('Intérêts de l\'impartition : moins de coûts fixes, investissements concentrés, flexibilité, organisation plus simple.')
    c.df('Alliance', 'Association entre entreprises concurrentes ou non pour obtenir des effets d\'échelle, une position internationale, l\'accès à une zone, un savoir-faire ou promouvoir un standard.')
    c.df('Avantage concurrentiel', 'Avantage temporaire, sorte de monopole de situation : performance supérieure due à la position de l\'entreprise face à la concurrence (définition du corrigé du cas L&L).')
    c.df('Facteur clé de succès', 'Élément de l\'offre ou de l\'organisation qu\'il faut maîtriser pour réussir dans un secteur.')
    c.synthese(['Marketing stratégique (direction) ≠ opérationnel (mise en œuvre) ; démarche SOSTAC.', 'Diagnostic : PESTEL, SWOT (attaque, ajustement, défense, survie), Porter 5 + 1.', 'Portefeuille : ADL, BCG (les vaches à lait financent les dilemmes et les stars), McKinsey ; ce sont des aides, pas des recettes.', 'Croissance interne : coûts, spécialisation, différenciation, innovation ; croissance externe : rachats, fusions, intégration, impartition, alliances.'])
    return c
